#include "stdafx.h"#include <rsuMemoryManager.h>#include <MemoryServiceH5xx.h>#include <rsuErr.h>#ifdef _MANAGED#pragma managed(push, off)#endifstatic KRsuMemoryManager s_memoryHW;static void* _ObjsMemAllocatorHW( size_t size ){  void* p = s_memoryHW.AllocMemory( (DWORD)size );  ASS( p );  return p;}BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    s_memoryHW.Create( "H5xx_Mem", 128 );    KMemoryServiceH5xx::Instance().InitMemAllocator( _ObjsMemAllocatorHW );    break;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endif